const ShareButton: React.FC<ShareButtonProps> = ({
  url,
  title,
  trigger,
  className = '',
}) => {
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const modalRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  // Check if mobile
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 640); // sm breakpoint
    };
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Close modal on ESC key
  useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && showShareModal) {
        setShowShareModal(false);
      }
    };

    if (showShareModal) {
      document.addEventListener('keydown', handleEscape);
      return () => document.removeEventListener('keydown', handleEscape);
    }
  }, [showShareModal]);

  // Close modal when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        setShowShareModal(false);
      }
    };

    if (showShareModal) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [showShareModal]);

  const handleOpenModal = () => {
    setShowShareModal(true);
    setCopied(false);
  };

  const handleShare = (platform: typeof socialPlatforms[0]) => {
    const shareUrl = platform.getShareUrl(url, title);

    // For mobile apps (WeChat, Viber, etc.), try to open the app
    if (shareUrl.startsWith('weixin://') || shareUrl.startsWith('viber://')) {
      window.location.assign(shareUrl);
    } else {
      // Open in new window
      window.open(shareUrl, '_blank', 'width=600,height=400,noopener,noreferrer');
    }
  };

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
      // Fallback for older browsers
      const textArea = document.createElement('textarea');
      textArea.value = url;
      textArea.style.position = 'fixed';
      textArea.style.opacity = '0';
      document.body.appendChild(textArea);
      textArea.select();
      try {
        document.execCommand('copy');
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } catch (fallbackErr) {
        console.error('Fallback copy failed:', fallbackErr);
      }
      document.body.removeChild(textArea);
    }
  };

  const defaultTrigger = (
    <motion.button
      onClick={handleOpenModal}
      whileTap={{ scale: 0.9 }}
      className={`flex flex-col items-center justify-center w-14 h-14 rounded-lg transition-colors duration-200 ${theme === 'dark' ? 'text-gray-400 hover:text-green-500 hover:bg-green-500/10' : 'text-gray-500 hover:text-green-500 hover:bg-green-500/10'}`}
    >
      <Share2 className="w-5 h-5" />
      <span className={`text-xs mt-0.5 ${theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}`}>0</span>
    </motion.button>
  );

  const handleTriggerClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    handleOpenModal();
  };

  return (
    <>
      {trigger ? (
        <div
          className={className}
          onClick={handleTriggerClick}
          style={{ pointerEvents: 'auto' }}
        >
          {React.isValidElement(trigger)
            ? React.cloneElement(trigger as React.ReactElement<any>, {
                onClick: (e: React.MouseEvent) => {
                  e.stopPropagation();
                  e.preventDefault();
                  handleOpenModal();
                },
                style: { pointerEvents: 'auto' as const, ...(trigger.props as any)?.style }
              })
            : trigger
          }
        </div>
      ) : (
        defaultTrigger
      )}

      {typeof window !== 'undefined' && createPortal(
        <AnimatePresence>
          {showShareModal && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-2 md:p-4"
              onClick={(e) => {
                // Only close if clicking directly on backdrop (not on modal content)
                if (e.target === e.currentTarget) {
                  setShowShareModal(false);
                }
              }}
              style={{
                backgroundColor: 'rgba(0, 0, 0, 0.5)',
                backdropFilter: 'blur(4px)',
              }}
            >
              <motion.div
                ref={modalRef}
                initial={{ 
                  opacity: 0, 
                  y: isMobile ? '100%' : 20,
                  scale: isMobile ? 1 : 0.95
                }}
                animate={{ 
                  opacity: 1, 
                  y: 0,
                  scale: 1
                }}
                exit={{ 
                  opacity: 0, 
                  y: isMobile ? '100%' : 20,
                  scale: isMobile ? 1 : 0.95
                }}
                transition={{ 
