import React, { useCallback } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { Users, RefreshCw } from 'lucide-react';
import { useTheme } from '../../contexts/ThemeContext';
import { useAuth } from '../../contexts/AuthContext';
import { useTranslation } from 'react-i18next';
import { api } from '../../services/api';
import { Actions } from '../../services/actions';
import { generateFallbackImage, getSafeImageURLEx } from '../../helpers/helpers';

interface PopularUsersPanelProps {
  limit?: number;
}

interface PopularUser {
  id: string;
  username: string;
  displayname: string;
  date_of_birth?: string;
  avatar?: {
    file?: {
      url?: string;
    };
  };
  profile_image_url?: string;
  engagements?: {
    counts?: {
      follower_count?: number;
    };
  };
  followers_count?: number;
}

const PopularUsersPanel: React.FC<PopularUsersPanelProps> = ({ limit = 20 }) => {
  const { theme } = useTheme();
  const { isAuthenticated } = useAuth();
  const navigate = useNavigate();
  const { t } = useTranslation('common');

  const [users, setUsers] = React.useState<PopularUser[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);

  const calculateAge = React.useCallback((dateOfBirth?: string): number | null => {
    if (!dateOfBirth) return null;
    const birthDate = new Date(dateOfBirth);
    if (Number.isNaN(birthDate.getTime())) return null;

    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDiff = today.getMonth() - birthDate.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
      age -= 1;
    }

    return age >= 0 ? age : null;
  }, []);

  const fetchPopularUsers = React.useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await api.fetchNearbyUsers({
        limit: limit,
        cursor: null,
      }) as { users?: PopularUser[] };

      const normalized = (response?.users ?? []).slice(0, limit);
      setUsers(normalized);
    } catch (err: any) {
      const message =
        err?.response?.data?.message ||
        err?.message ||
        'Fetch error';
      setError(message);
    } finally {
      setIsLoading(false);
    }
  }, [limit]);

  React.useEffect(() => {
    fetchPopularUsers();
  }, [limit, fetchPopularUsers]);

  const resolveAvatar = useCallback((user: PopularUser) => {
    return (
      getSafeImageURLEx(user.username, (user as any).avatar, 'icon') as string
    );
  }, []);





  const handleAvatarError = (e: React.SyntheticEvent<HTMLImageElement, Event>, user: PopularUser) => {
    const target = e.currentTarget;
    target.onerror = null; // sonsuz döngüyü önlemek için
    target.src = generateFallbackImage(user.username);
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4">
          {Array.from({ length: limit }).map((_, index) => (
            <div
              key={`popular-skeleton-${index}`}
              className={`relative overflow-hidden rounded-3xl border ${theme === 'dark' ? 'border-gray-900 bg-gray-950' : 'border-gray-100 bg-gray-50'
                } aspect-[3/4] animate-pulse`}
            >
              <div className="absolute inset-0">
                <div className={`h-2/3 w-full ${theme === 'dark' ? 'bg-gray-900' : 'bg-gray-200'}`} />
                <div className={`h-1/3 w-full ${theme === 'dark' ? 'bg-gray-800' : 'bg-gray-300'}`} />
              </div>
              <div className="absolute inset-x-0 bottom-0 p-4">
                <div className={`h-4 w-24 rounded ${theme === 'dark' ? 'bg-gray-700/60' : 'bg-gray-300'}`} />
                <div className={`mt-2 h-3 w-16 rounded ${theme === 'dark' ? 'bg-gray-800/70' : 'bg-gray-200'}`} />
              </div>
            </div>
          ))}
        </div>
      );
    }

    if (error) {
      return (
        <div
          className={`rounded-2xl border p-4 ${theme === 'dark'
            ? 'border-red-900/40 bg-red-900/10 text-red-200'
            : 'border-red-100 bg-red-50 text-red-600'
            }`}
        >
          <p className="text-sm font-medium">{error}</p>
          <button
            type="button"
            onClick={fetchPopularUsers}
            className={`mt-3 inline-flex items-center gap-2 rounded-xl px-3 py-2 text-sm font-semibold transition-colors ${theme === 'dark'
              ? 'bg-red-800/60 text-red-100 hover:bg-red-800/80'
              : 'bg-red-100 text-red-700 hover:bg-red-200'
              }`}
          >
            <RefreshCw className="h-4 w-4" />
            {t('app.popular_users_retry')}
          </button>
        </div>
      );
    }

    if (users.length === 0) {
      return (
        <div
          className={`rounded-2xl border p-5 text-center ${theme === 'dark' ? 'border-gray-900 bg-gray-950 text-gray-400' : 'border-gray-200 bg-white text-gray-500'
            }`}
        >
          <Users className="mx-auto mb-3 h-6 w-6" />
          <p className="text-sm font-medium">{t('app.popular_users_empty')}</p>
        </div>
      );
    }


    return (
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4">
        {users.map((user, index) => {
          const age = calculateAge(user.date_of_birth);
          return (
            <motion.button
              key={`${user.id ?? user.public_id ?? user.username ?? 'user'}-${index}`}
              type="button"
              onClick={() => navigate(`/${user.username}`)}
              initial={{ opacity: 0, y: 18 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.04 }}
              className={`group relative overflow-hidden rounded-3xl border ${theme === 'dark'
                ? 'border-gray-900 bg-gray-950 hover:border-indigo-500/40 hover:shadow-indigo-500/20'
                : 'border-gray-100 bg-white hover:border-gray-300 hover:shadow-[0_12px_30px_-16px_rgba(79,70,229,0.55)]'
                } aspect-[3/4] transition-all`}
            >
              <img
                src={resolveAvatar(user)}
                onError={(e) => handleAvatarError(e, user)}
                alt={user.displayname || user.username}
                className={`absolute inset-0 h-full w-full object-cover transition-transform duration-500 group-hover:scale-105 ${!isAuthenticated ? 'blur-md' : ''
                  }`}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/30 to-transparent opacity-90 transition-opacity duration-300 group-hover:opacity-95" />
              <div className="absolute inset-x-0 bottom-0 flex flex-col gap-1 p-4 text-left">
                <p className="truncate text-base font-semibold text-white text-sm">
                  {user.displayname || user.username}
                </p>
                <p className="text-sm font-medium text-white/80">
                  {age !== null
                    ? t('app.popular_users_age_years', {
                      age,
                      defaultValue: `${age} ${t('app.popular_users_age_suffix', { defaultValue: 'yaş' })}`,
                    })
                    : ""}
                </p>
              </div>
            </motion.button>
          );
        })}
      </div>
    );
  };

  return (
    <motion.section
      initial={{ opacity: 0, y: 16 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35 }}
      className={`rounded-3xl border p-5 sm:p-6 ${theme === 'dark' ? 'border-gray-900 bg-gray-950/90' : 'border-gray-100 bg-white'
        }`}
    >
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className={`text-[10px] font-semibold uppercase tracking-[0.4em] ${theme === 'dark' ? 'text-gray-500' : 'text-gray-400'}`}>
            {t('app.popular_users_badge')}
          </p>
          <h3 className={`mt-1 text-lg font-bold ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
            {t('app.popular_users_title')}
          </h3>
          <p className={`mt-1 text-xs ${theme === 'dark' ? 'text-gray-400' : 'text-gray-500'}`}>
            {t('app.popular_users_subtitle')}
          </p>
        </div>
        <div className={`rounded-2xl p-3 ${theme === 'dark' ? 'bg-white/10 text-white' : 'bg-gray-100 text-gray-700'}`}>
          <Users className="h-6 w-6" />
        </div>
      </div>

      <div className="mt-4">{renderContent()}</div>
    </motion.section>
  );
};

export default PopularUsersPanel;

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TrendingUp, RefreshCw, ExternalLink, Search, Loader2, ArrowUpRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useTheme } from '../../contexts/ThemeContext';
import { api } from '../../services/api';
import { Actions } from '../../services/actions';

type RawTrend = Record<string, any> | string;

export interface NormalizedTrend {
  id: string;
  label: string;
  subtitle?: string | null;
  volume?: number | null;
  change?: number | null;
  url?: string | null;
  query?: string | null;
  raw: RawTrend;
  rank: number;
}

interface TrendsPanelProps {
  limit?: number;
  onTrendSelect?: (trend: NormalizedTrend) => void;
}

const formatNumber = (value: number) => {
  if (!Number.isFinite(value)) {
    return null;
  }

  if (value >= 1_000_000) {
    return `${(value / 1_000_000).toFixed(1).replace(/\.0$/, '')}M`;
  }
  if (value >= 1_000) {
    return `${(value / 1_000).toFixed(1).replace(/\.0$/, '')}K`;
  }
  return value.toLocaleString();
};

const normalizeTrends = (data: any, fallbackTitle: string): NormalizedTrend[] => {
  if (!data) return [];

  const list: RawTrend[] =
    Array.isArray(data) ? data : data?.trends ?? data?.items ?? data?.data ?? [];

  return list
    .map<NormalizedTrend | null>((item, index) => {
      if (item == null) return null;

      if (typeof item === 'string') {
        return {
          id: `${index}-${item}`,
          label: item,
          subtitle: null,
          volume: null,
          change: null,
          url: null,
          query: item,
          raw: item,
          rank: index + 1,
        };
      }

      const label =
        item.title ??
        item.name ??
        item.query ??
        item.topic ??
        item.label ??
        item.keyword ??
        fallbackTitle;

      const subtitle =
        item.subtitle ??
        item.category ??
        item.context ??
        item.location ??
        item.description ??
        null;

      const volume =
        item.volume ??
        item.total ??
        item.count ??
        item.searchVolume ??
        item.tweet_volume ??
        item.popularity ??
        null;

      const change =
        item.change ??
        item.delta ??
        item.score ??
        item.spark ??
        (typeof item.trend_change === 'number' ? item.trend_change : null) ??
        null;

      const url =
        item.url ??
        item.link ??
        item.permalink ??
        (typeof item.target === 'string' ? item.target : null) ??
        null;

      const query =
        item.query ??
        item.keyword ??
        item.searchQuery ??
        item.slug ??
        item.hashtag ??
        label;

      const id =
        item.id ??
        item.key ??
        item.slug ??
        item.query ??
        `${index}-${label}`;

      return {
        id: String(id),
        label: String(label),
        subtitle: subtitle ? String(subtitle) : null,
        volume: typeof volume === 'number' ? volume : Number(volume) || null,
        change: typeof change === 'number' ? change : Number(change) || null,
        url: url ? String(url) : null,
        query: query ? String(query) : null,
        raw: item,
        rank: index + 1,
      };
    })
    .filter((item): item is NormalizedTrend => Boolean(item));
};

const rainbowRankStyles: Array<{ background: string; color: string }> = [
  {
    background: 'linear-gradient(135deg, #FF3B30 0%, #FF6B3B 100%)',
    color: '#ffffff',
  },
  {
    background: 'linear-gradient(135deg, #FF9500 0%, #FFD60A 100%)',
    color: '#1f2937',
  },
  {
    background: 'linear-gradient(135deg, #FFD60A 0%, #34C759 100%)',
    color: '#1f2937',
  },
  {
    background: 'linear-gradient(135deg, #34C759 0%, #32D74B 100%)',
    color: '#ffffff',
  },
  {
    background: 'linear-gradient(135deg, #007AFF 0%, #5AC8FA 100%)',
    color: '#ffffff',
  },
  {
    background: 'linear-gradient(135deg, #5856D6 0%, #5E5CE6 100%)',
    color: '#ffffff',
  },
  {
    background: 'linear-gradient(135deg, #AF52DE 0%, #FF2D55 100%)',
    color: '#ffffff',
  },
];

const getRankStyle = (rank: number) => {
  if (rank <= rainbowRankStyles.length) {
    return rainbowRankStyles[rank - 1];
  }

  const hue = (rank * 47) % 360;
  const nextHue = (hue + 30) % 360;

  return {
    background: `linear-gradient(135deg, hsl(${hue}, 85%, 55%) 0%, hsl(${nextHue}, 80%, 60%) 100%)`,
    color: '#ffffff',
  };
};

const TrendsPanel: React.FC<TrendsPanelProps> = ({ limit = 20, onTrendSelect }) => {
  const { theme } = useTheme();
  const { t } = useTranslation('common');
  const [trends, setTrends] = React.useState<NormalizedTrend[]>([]);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = React.useState<Date | null>(null);
  const [isExpanded, setIsExpanded] = React.useState(false);

  const fetchTrends = React.useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await api.fetchTrends({ limit });

      let normalized: NormalizedTrend[] = [];

      if (Array.isArray(response?.trends)) {
        normalized = response.trends
          .slice(0, limit)
          .map((item: any, index: number): NormalizedTrend => {
            const tag = item?.tag ?? item?.keyword ?? item?.title ?? `Trend ${index + 1}`;
            const count = typeof item?.count === 'number' ? item.count : Number(item?.count) || null;

            return {
              id: String(item?.id ?? item?.tag ?? index),
              label: String(tag),
              subtitle: null,
              volume: count,
              change: null,
              url: null,
              query: String(tag),
              raw: item,
              rank: index + 1,
            };
          });
      } else {
        normalized = normalizeTrends(
          response,
          'Trending'
        );
      }

      setTrends(normalized);
      const apiTimestamp = response?.last_update ?? response?.last_updated;
      setLastUpdated(apiTimestamp ? new Date(apiTimestamp) : new Date());
      setIsExpanded(false);
    } catch (err: any) {
      console.error('Failed to fetch trends', err);
      setError(err?.response?.data?.message || err?.message || 'Error loading trends');
    } finally {
      setLoading(false);
    }
  }, [limit]);

  React.useEffect(() => {
    fetchTrends();
  }, [fetchTrends]);

  const handleSelect = React.useCallback((trend: NormalizedTrend) => {
    if (onTrendSelect) {
      onTrendSelect(trend);
      return;
    }

    if (trend.url) {
      window.open(trend.url, '_blank', 'noopener,noreferrer');
      return;
    }

    if (trend.query) {
      const encoded = encodeURIComponent(trend.query);
      window.location.href = `/search?q=${encoded}`;
    }
  }, [onTrendSelect]);

  const subtitleColor = theme === 'dark' ? 'text-gray-400' : 'text-gray-500';
  const cardBackground =
    theme === 'dark'
      ? 'bg-gradient-to-br from-gray-950/95 via-gray-900/90 to-gray-950/95 backdrop-blur-xl'
      : 'bg-gradient-to-br from-white via-white/97 to-gray-50';

  const MAX_COMPACT_ITEMS = 7;
  const hasOverflow = trends.length > MAX_COMPACT_ITEMS;
  const displayedTrends = isExpanded ? trends : trends.slice(0, MAX_COMPACT_ITEMS);
  const hiddenCount = hasOverflow ? trends.length - MAX_COMPACT_ITEMS : 0;

  return (
    <motion.div
      initial={{ opacity: 0, y: 16 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.25, ease: 'easeOut' }}
      className={`rounded-3xl overflow-hidden ${cardBackground}`}
    >
      <div className="p-5 pb-4 flex items-start justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <TrendingUp className={`w-5 h-5 ${theme === 'dark' ? 'text-indigo-300' : 'text-indigo-500'}`} />
            <h2 className={`text-lg font-bold ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
              {t('app.trending_title')}
            </h2>
          </div>
          <p className={`text-sm ${subtitleColor}`}>
            {t('app.trending_subtitle')}
          </p>
          {lastUpdated && (
            <div className="mt-3 flex items-center gap-2">
              <span
                className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-semibold ${theme === 'dark' ? 'bg-white/10 text-gray-200' : 'bg-gray-100 text-gray-600'
                  }`}
              >
                <span className="inline-block w-1.5 h-1.5 rounded-full bg-current" />
                {t('app.trending_updated', {
                  time: lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                })}
              </span>
              {trends.length > 0 && (
                <span
                  className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-semibold ${theme === 'dark' ? 'bg-white/5 text-gray-300' : 'bg-gray-50 text-gray-600'
                    }`}
                >
                  #{trends.length}
                </span>
              )}
            </div>
          )}
        </div>
        <button
          type="button"
          onClick={fetchTrends}
          className={`p-2 rounded-full transition-colors ${theme === 'dark'
            ? 'hover:bg-white/15 text-gray-300'
            : 'hover:bg-gray-100 text-gray-600'
            }`}
          aria-label={t('app.trending_refresh')}
        >
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
        </button>
      </div>

      <div className="px-5 pb-5 space-y-3">
        {error ? (
          <div
            className={`rounded-2xl p-4 ${theme === 'dark'
              ? 'bg-red-500/15 text-red-200 shadow-[0_14px_32px_-22px_rgba(248,113,113,0.7)]'
              : 'bg-red-50 text-red-600 shadow-[0_14px_28px_-20px_rgba(248,113,113,0.45)]'
              }`}
          >
            <p className="text-sm font-medium mb-3">{error}</p>
            <button
              type="button"
              onClick={fetchTrends}
              className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-semibold transition-colors ${theme === 'dark'
                ? 'bg-red-500/30 text-red-100 hover:bg-red-500/40'
                : 'bg-red-100 text-red-600 hover:bg-red-200'
                }`}
            >
              <RefreshCw className="w-3.5 h-3.5" />
              {t('app.trending_retry')}
            </button>
          </div>
        ) : (
          <>
            <AnimatePresence initial={false}>
              {loading && trends.length === 0 ? (
                <motion.div
