              <div className="px-3.5 py-1.5 rounded-xl bg-gray-950/95 border border-white/10 shadow-2xl backdrop-blur-md">
                <span className="text-[11px] font-black tracking-widest text-white uppercase whitespace-nowrap">
                  {name}
                </span>
              </div>
            </div>
          </div>
        ),
        anchor: [30, 78],
      })}
      eventHandlers={{
        click: () => onClick(place),
      }}
    />
  );
};

