import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { MoreVertical } from 'lucide-react';
import { getSafeImageURLEx } from '../../../helpers/helpers';

export interface Notification {
  id: string;
  sender_id: string;
  sender: {
    public_id: string;
    id: string;
    username: string;
    displayname: string;
    avatar?: string;
    [key: string]: any;
  };
  user_id: string;
  type: string;
  title: string;
  message: string;
  payload: {
    title: string;
    body: string;
    [key: string]: any;
  };
  is_read: boolean;
  is_shown: boolean;
  created_at: string;
}

interface NotificationItemProps {
  notification: Notification;
  markAsRead: (id: string) => void;
  onClick: () => void;
  theme: string;
  getNotificationIcon: (type: string) => React.ComponentType<any>;
  formatTime: (createdAt: string) => string;
  index: number;
  isLast: boolean;
}

const NotificationItem: React.FC<NotificationItemProps> = ({
  notification,
  markAsRead,
  onClick,
  theme,
  getNotificationIcon,
  formatTime,
  index,
  isLast
}) => {
  const ref = useRef<HTMLDivElement>(null);
  const Icon = getNotificationIcon(notification.type);
  const isDark = theme === 'dark';

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !notification.is_read) {
          markAsRead(notification.id);
        }
      },
      { threshold: 0.5 }
    );

    if (ref.current) observer.observe(ref.current);
    return () => {
      if (ref.current) observer.unobserve(ref.current);
    };
  }, [notification.id, notification.is_read, markAsRead]);

  return (
    <motion.div
      key={notification.id}
      ref={ref}
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, x: -20 }}
      transition={{ 
        delay: index * 0.02, 
        duration: 0.4,
        ease: [0.22, 1, 0.36, 1]
      }}
      onClick={onClick}
      className={`group relative px-4 py-5 cursor-pointer transition-all duration-300 ${
        !isLast ? `border-b ${isDark ? 'border-gray-900/40' : 'border-gray-100/60'}` : ''
      } ${
        !notification.is_read 
          ? isDark 
            ? 'bg-gradient-to-r from-white/[0.03] to-transparent hover:from-white/[0.05]' 
            : 'bg-gradient-to-r from-black/[0.015] to-transparent hover:from-black/[0.03]'
          : isDark
            ? 'hover:bg-gray-900/30'
            : 'hover:bg-gray-50/70'
      }`}
    >
      <div className="flex items-start gap-4">
        {/* Interaction Icon with Premium Backdrop */}
        <div className="relative flex-shrink-0">
          <div className={`w-12 h-12 rounded-[20px] flex items-center justify-center transition-all duration-300 transform group-hover:scale-105 ${
            isDark 
              ? 'bg-gray-900/60 group-hover:bg-gray-800' 
              : 'bg-gray-100 group-hover:bg-gray-200/50'
          }`}>
            <Icon className={`w-5 h-5 ${
              isDark ? 'text-gray-400 group-hover:text-white' : 'text-gray-500 group-hover:text-gray-900'
            }`} strokeWidth={1.5} />
          </div>

          {/* Avatar Pin */}
          <div className={`absolute -bottom-1 -right-1 w-6 h-6 rounded-full overflow-hidden border-2 group-hover:scale-110 transition-transform duration-300 ${
            isDark ? 'border-gray-950 bg-gray-900' : 'border-white bg-gray-100 shadow-sm'
          }`}>
            <img
              src={getSafeImageURLEx(notification.sender?.public_id, notification.sender?.avatar || undefined, 'thumbnail') || undefined}
              alt={notification.sender.username}
              className="w-full h-full object-cover"
            />
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 min-w-0 pt-0.5">
          <div className="flex items-start justify-between gap-3">
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-1">
                <span className={`text-[15px] font-bold tracking-tight truncate ${isDark ? 'text-white' : 'text-gray-900'}`}>
                  {notification.sender?.displayname || notification.sender?.username}
                </span>
                {!notification.is_read && (
                  <motion.span 
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    className={`w-1.5 h-1.5 rounded-full ${isDark ? 'bg-white shadow-[0_0_8px_rgba(255,255,255,0.6)]' : 'bg-black'}`} 
                  />
                )}
              </div>

              <p className={`text-[14px] leading-[1.6] mb-2.5 font-medium ${isDark ? 'text-gray-300/90' : 'text-gray-600'}`}>
                {notification.message}
              </p>

              <div className="flex items-center gap-3">
                <span className={`text-[11px] font-bold uppercase tracking-wider opacity-60 ${isDark ? 'text-gray-400' : 'text-gray-500'}`}>
                  {formatTime(notification.created_at)}
                </span>
              </div>
            </div>

            {/* Subtle Menu Trigger */}
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={(e) => {
                e.stopPropagation();
              }}
              className={`p-2 rounded-full opacity-0 group-hover:opacity-100 transition-all ${
                isDark ? 'hover:bg-gray-800 text-gray-400 hover:text-white' : 'hover:bg-gray-100 text-gray-500 hover:text-gray-900'
              }`}
            >
              <MoreVertical className="w-4 h-4" />
            </motion.button>
          </div>
        </div>
      </div>
    </motion.div>
  );
};

export default NotificationItem;

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import './style.css';
import { useAtom } from 'jotai';
import { globalState } from '../../../state/nearby'; // atomun tanımlı olduğu dosya
import { calculateAge } from '../../../helpers/helpers';
import { ActionBar } from '../../profile/UserCard/ActionBar';
import { api } from '../../../services/api';
import { useNavigate } from 'react-router-dom';
import { useTheme } from '../../../contexts/ThemeContext';
import { AnimatePresence, motion } from 'framer-motion';
import { useWebGLSphere } from '../../../hooks/useWebGLSphere';


const defaultItems = [
    {
        image: 'https://picsum.photos/900/900?grayscale',
        link: 'https://google.com/',
        title: '',
        description: ''
    }
];

export default function BubbleView() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [state, setState] = useAtom(globalState);

    const [activeItem, setActiveItem] = useState(null);
    const [isMoving, setIsMoving] = useState(false);

    const [isGiftSelectorOpen, setIsGiftSelectorOpen] = useState(false);
    const [isQuickMessageSelectorOpen, setIsQuickMessageSelectorOpen] = useState(false);
    const [liked, setLiked] = useState(false);
    const [disliked, setDisliked] = useState(false)
    const [blocked, setIsBlocked] = useState(false)
    const navigate = useNavigate();
    const { theme } = useTheme();
    const [activeUser, setActiveUser] = useState<any | null>(null);

    const baseCardStyle =
        theme === 'dark'
            ? 'bg-gray-950 border border-gray-900 text-white'
            : 'bg-white border border-gray-100 text-black';

    const baseButtonStyle =
        theme === 'dark'
            ? 'border border-gray-700 text-gray-400 hover:bg-gray-950 hover:text-white'
            : 'border border-gray-300 text-gray-700 hover:bg-gray-400 hover:text-gray-900';

    useEffect(() => {
        console.log(state.nearbyUsers)
    }, []);

    useEffect(() => {
        const handleUserBlocked = (e: unknown) => {
            const blockedId = e.detail?.userId;
            if (activeUser && (activeUser.public_id === blockedId || activeUser.id === blockedId)) {
                setActiveUser(null);
            }
        };
        window.addEventListener('userBlocked', handleUserBlocked);
        return () => window.removeEventListener('userBlocked', handleUserBlocked);
    }, [activeUser]);



    const users = useMemo(() => state.nearbyUsers.length ? state.nearbyUsers : defaultItems, [state.nearbyUsers]);

    const handleActiveItemChange = useCallback((index: number) => {
        const itemIndex = index % users.length;
        setActiveUser(users[itemIndex]);
    }, [users]);

    const webglController = useWebGLSphere(canvasRef, users, handleActiveItemChange, setIsMoving);






    const handleSendMessage = async (profile: unknown) => {
        if (!profile?.id) {
            console.error('User or profile ID is missing');
            return;
        }

        try {
            // Create chat via API
            const chatResponse = await api.createChat([profile.id], 'private') as {
                chat: {
                    id: string;
                    type: string;
                    participants?: Array<{
                        user_id: string;
                        user?: {
                            id: string;
                            username?: string;
                            displayname?: string;
                        };
                    }>;
                };
                success: boolean;
            };

            const chatId = chatResponse?.chat?.id;

            if (chatId) {
                // Navigate to messages screen with chat ID
                navigate('/messages', {
                    state: {
                        openChat: chatId,
                        userId: profile.id,
                        publicId: profile.public_id,
                        username: profile.username
                    }
                });
            } else {
                console.error('Chat creation failed - no chat ID returned');
            }
        } catch (error) {
            console.error('Error creating chat:', error);
            // Navigate anyway, MessagesScreen will handle creating a temporary chat
            navigate('/messages', {
                state: {
                    openChat: profile.username || profile.id,
                    userId: profile.id,
                    publicId: profile.public_id
                }
            });
        }
    };

    const handleSendLike = async (user: unknown) => {
        //


        if (!user?.public_id) return;

        try {
            await api.toggleUserLike({
                likee_id: user.public_id,
            });


        } catch (error) {
            console.error('Error toggling like:', error);
            // Optionally show error message to user
        }
    }

    const handleSendDislike = async (user: unknown) => {
        //


        if (!user?.public_id) return;

        try {
            await api.toggleUserDislike({
                likee_id: user.public_id,
            });


        } catch (error) {
            console.error('Error toggling like:', error);
            // Optionally show error message to user
        }
    }

    const handleBlock = async (user: unknown) => {
        //


        if (!user?.public_id) return;

        try {
            await api.toggleBlockUser(user.public_id);
        } catch (error) {
            console.error('Error toggling like:', error);
            // Optionally show error message to user
        }
    }



    return (
        <div style={{ position: 'relative', width: '100%', height: '100%' }}>
            <canvas id="infinite-grid-menu-canvas" ref={canvasRef} />
            <AnimatePresence>
                {activeUser && !isMoving && (
                    <motion.div
                        className="absolute bottom-0 left-0 right-0 h-1/4 md:h-1/5 flex flex-col items-center justify-center"
                        initial={{ opacity: 0, y: 50 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 50 }}
                        transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
                    >
                        <div className={` w-full max-w-sm flex flex-col gap-2 items-center justify-center text-center`}>
                            <h2 className="text-md font-bold">{activeUser?.username} <span className="font-light">{calculateAge(activeUser.date_of_birth)}</span></h2>
                            <ActionBar
                                viewMode='bubble'
                                liked={liked}
                                disliked={disliked}
                                blocked={blocked}
                                onBlockToggle={() => {
                                    setIsBlocked((prev) => !prev)
                                    handleBlock(activeUser)
                                }}
                                onLikeToggle={() => {
                                    setLiked((prev) => !prev)
                                    handleSendLike(activeUser)
                                }}
                                onDislikeToggle={() => {
                                    setDisliked((prev) => !prev)
                                    handleSendDislike(activeUser)
                                }}
                                onOpenGiftSelector={() => setIsGiftSelectorOpen(true)}
                                onOpenQuickMessageSelector={() => {
                                    handleSendMessage(activeUser)
                                }}
                                baseButtonStyle={baseButtonStyle}
                                onTriggerOverlay={() => { }}
                            />
                        </div>




                    </motion.div>)}
            </AnimatePresence>


        </div>
    );
}

