        const label = eventKind.name?.[defaultLanguage] || eventKind.name?.en || eventKind.kind;
        const desc = eventKind.description?.[defaultLanguage] || eventKind.description?.en || '';

        return {
          value: eventKind.kind,
          label: label,
          desc: desc
        };
      });
