                  : 'bg-black text-white disabled:bg-gray-200 disabled:text-gray-500'
                  }`}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                {isSubmitting ? "Posting..." : buttonText}
              </motion.button>
            </div>
          </div>
        </div>
      </motion.div>
    </div>
  );
};

export default CreatePost;

