const resolveTagIcon = (icon?: string | LucideIcon): LucideIcon => {
  if (!icon) return MapPin;
  if (typeof icon === 'function') return icon as LucideIcon;
  const key = icon.toLowerCase();
  return LUCIDE_ICON_MAP[key] ?? MapPin;
};

