                                    {percentage}%
                                  </span>
                                </div>
                              </motion.div>
                            );
                          });
                        })() : (
                          <div className={`text-center py-4 ${theme === 'dark' ? 'text-white/50' : 'text-gray-500'}`}>
                            <span className="text-xs font-medium">No choices available for this poll.</span>
                          </div>
                        )}
                      </div>

                      {/* Compact Selection Info */}
                      {hasSelectedChoices && (
                        <motion.div
                          initial={{ opacity: 0 }}
                          animate={{ opacity: 1 }}
