                                    const updated = { ...prev };
                                    delete updated[poll.id];
                                    return updated;
                                  });
                                }}
                                onMouseDown={(e) => e.stopPropagation()}
                                onPointerDown={(e) => e.stopPropagation()}
                                onTapStart={(e) => e.stopPropagation()}
