                        ? 'bg-white text-black'
                        : 'bg-black text-white'
                      : theme === 'dark'
                        ? 'border border-gray-700 text-white/90 hover:bg-gray-900/50'
                        : 'border border-gray-300/60 hover:bg-gray-50'
                      }`}
                  >
                    Not Going
