import React, {
    useState,
    useRef,
    useEffect,
    useCallback,
    useMemo
} from "react";
import { useAtom } from "jotai";
import { globalState } from "../../../state/nearby";
import { VibeItem } from "./VibeItem";
import { api } from "../../../services/api";
import { getSafeImageURL, getSafeImageURLEx } from "../../../helpers/helpers";
import { defaultServiceServerId, serviceURL } from "../../../appSettings";
import { useWebGLCoverflow } from "../../../hooks/useWebGLCoverflow";
import { Volume2, VolumeX, Loader2, Sparkles } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

const VibesGL: React.FC = () => {
    const [state, setState] = useAtom(globalState);

    const [activeIndex, setActiveIndex] = useState(0);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    const [isLoading, setIsLoading] = useState(true);
    const [hasMore, setHasMore] = useState(true);

    const vibes = useMemo(() => state.vibes ?? [], [state.vibes]);
    const [isMuted, setIsMuted] = useState(false);

    // Refs for safe fetching
    const cursorRef = useRef(state.vibesCursor);
    const hasMoreRef = useRef(true);
    const isFetchingRef = useRef(false);

    useEffect(() => {
        cursorRef.current = state.vibesCursor;
    }, [state.vibesCursor]);

    useEffect(() => {
        hasMoreRef.current = hasMore;
    }, [hasMore]);

    // FETCH FUNCTION
    const fetchVibesFromAPI = useCallback(
        async (loadMore = false) => {
            if (isFetchingRef.current) return;
            if (loadMore && !hasMoreRef.current) return;

            try {
                isFetchingRef.current = true;
                if (!loadMore) setIsLoading(true);

                const currentCursor = loadMore ? (cursorRef.current?.toString?.() || "") : "";

                const response = await api.fetchVibes({
                    limit: 15, // Increased limit for smoother experience
                    cursor: currentCursor
                });

                const posts = response.posts || [];
                const incomingVibes = posts
                    .filter((post: any) => post.attachments?.length > 0)
                    .map((post: any) => {
                        const attachment = post.attachments[0];
                        const file = attachment.file;
                        const author = post.author;

                        const mimeType = file?.mime_type || "";
                        const isVideo = mimeType.startsWith("video/");

                        let mediaUrl = "";
                        let posterUrl = "";

                        if (isVideo) {
                            mediaUrl =
                                getSafeImageURL(attachment, "high") ||
                                getSafeImageURL(attachment, "medium") ||
                                getSafeImageURL(attachment, "low") ||
                                getSafeImageURL(attachment, "preview") ||
                                getSafeImageURL(attachment, "original") ||
                                "";

                            if (!mediaUrl && file?.storage_path) {
                                const serviceURI = serviceURL[defaultServiceServerId];
                                const path = file.storage_path.replace(/^\.\//, "");
                                mediaUrl = `${serviceURI}/${path}`;
                            }

                            posterUrl = getSafeImageURL(attachment, "poster") || "";
                        } else {
                            mediaUrl =
                                getSafeImageURL(attachment, "large") ||
                                getSafeImageURL(attachment, "medium") ||
                                getSafeImageURL(attachment, "small") ||
                                getSafeImageURL(attachment, "original") ||
                                "";
                        }

                        const avatar = getSafeImageURLEx(author.public_id, author.avatar, "small");

                        return {
                            id: post.public_id,
                            mediaUrl,
                            mediaType: isVideo ? "video" : "image",
                            posterUrl: isVideo ? posterUrl : undefined,
                            username: author.username || "Unknown",
                            date_of_birth: author.date_of_birth,
                            avatar,
                            description: file?.name || "Vibe",
                            author: author
                        };
                    });

                setState(prev => {
                    if (!loadMore) {
                        return {
                            ...prev,
                            vibes: incomingVibes,
                            vibesCursor: response?.cursor ?? null
                        };
                    }

                    const existingIds = new Set(prev.vibes.map((v: any) => v.id));
                    const filtered = incomingVibes.filter((v: any) => !existingIds.has(v.id));

                    return {
                        ...prev,
                        vibes: [...prev.vibes, ...filtered],
                        vibesCursor: response?.cursor ?? prev.vibesCursor
                    };
                });

                const cursorVal = response?.cursor != null ? String(response.cursor) : '';
                const hasMorePosts = cursorVal !== '' && cursorVal !== '0' && cursorVal !== 'null' && cursorVal !== 'undefined';

                setHasMore(hasMorePosts);
                cursorRef.current = response?.cursor ?? null;
                hasMoreRef.current = hasMorePosts;

            } catch (err) {
                console.error("fetchVibes error:", err);
            } finally {
                if (!loadMore) setIsLoading(false);
                isFetchingRef.current = false;
            }
        },
        [setState]
    );

    // Initial Load
    useEffect(() => {
        if (!state.vibes || state.vibes.length === 0) {
            fetchVibesFromAPI(false);
        } else {
            setIsLoading(false);
        }
    }, [fetchVibesFromAPI, state.vibes]);

    // Infinite Scroll
    useEffect(() => {
        // Trigger load more when we reach the last 5 items
        if (vibes.length > 0 && hasMoreRef.current && activeIndex >= vibes.length - 5) {
            fetchVibesFromAPI(true);
        }
    }, [activeIndex, vibes.length, fetchVibesFromAPI]);

    const [isMediaLoading, setIsMediaLoading] = useState(false);

    useWebGLCoverflow({
        canvasRef: canvasRef as React.RefObject<HTMLCanvasElement>,
        vibes,
        onActiveIndexChange: setActiveIndex,
        isMuted: isMuted,
        onActiveMediaLoadingChange: setIsMediaLoading
    });

    const currentVibe = useMemo(() => vibes[activeIndex], [vibes, activeIndex]);

    return (
        <div
            className="relative w-full h-full overflow-hidden bg-black"
            style={{ cursor: "grab" }}
        >
            <AnimatePresence>
                {(isLoading || isMediaLoading) && (
                    <motion.div 
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="absolute inset-0 z-50 flex items-center justify-center text-white bg-black/60 backdrop-blur-md pointer-events-none"
                    >
                        <div className="flex flex-col items-center">
                            <div className="relative">
                                <Loader2 className="w-12 h-12 text-white/20 animate-spin" />
                                <Sparkles className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-5 h-5 text-white animate-pulse" />
                            </div>
                            <p className="mt-6 text-[15px] font-bold tracking-widest uppercase opacity-80">Loading Vibes</p>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {!isLoading && vibes.length === 0 && (
                <div className="absolute inset-0 z-40 flex flex-col items-center justify-center text-white bg-black">
                    <div className="w-20 h-20 bg-gray-900/50 rounded-[32px] flex items-center justify-center mb-6">
                        <Sparkles className="w-10 h-10 text-gray-700" />
                    </div>
                    <h2 className="text-xl font-bold tracking-tight">No Vibes Found</h2>
                    <p className="text-gray-500 mt-2 text-[14px]">Check back later for new discoveries.</p>
                </div>
            )}

            <div className="absolute top-6 right-6 z-20 flex gap-3">
                <button
                    onClick={() => setIsMuted(m => !m)}
                    className="p-3 bg-black/40 hover:bg-black/60 rounded-full text-white backdrop-blur-xl border border-white/10 transition-all active:scale-90"
                    aria-label={isMuted ? "Unmute" : "Mute"}
                >
                    {isMuted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                </button>
            </div>

            <canvas
                ref={canvasRef}
                className="absolute inset-0 w-full h-full"
            />
            {currentVibe && <VibeItem key={currentVibe.id} vibe={currentVibe} />}
        </div >
    );
};

export default VibesGL;

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { motion } from 'framer-motion';
import { Search, X, AlertCircle, Youtube } from 'lucide-react';
import { useTheme } from '../../contexts/ThemeContext';
import { YOUTUBE_API_KEY } from '../../appSettings';

export type YouTubeVideo = {
  id: string;
  title: string;
  description: string;
  channelTitle: string;
  publishedAt: string;
  thumbnail: string;
};

interface YouTubePickerProps {
  onVideoSelect: (video: YouTubeVideo) => void;
  onClose: () => void;
  isProcessing?: boolean;
}

type YouTubeApiSearchResult = {
  id: { videoId?: string } | string;
  snippet?: {
    title?: string;
    description?: string;
    channelTitle?: string;
    publishedAt?: string;
    thumbnails?: {
      medium?: { url?: string };
      high?: { url?: string };
    };
  };
};

const YOUTUBE_CATEGORIES = [
  { id: 'lgbt', label: 'LGBTQ+', endpoint: 'search' as const, query: 'LGBTQ+ videos' },
  { id: 'lgbt_music', label: 'LGBTQ+ Music', endpoint: 'search' as const, query: 'LGBTQ+ music videos' },
  { id: 'lgbt_news', label: 'LGBTQ+ News', endpoint: 'search' as const, query: 'LGBTQ+ news' },
  { id: 'trending', label: 'Trending', endpoint: 'videos' as const, params: { chart: 'mostPopular' } },
  { id: 'music', label: 'Music', endpoint: 'search' as const, query: 'music video' },
  { id: 'gaming', label: 'Gaming', endpoint: 'search' as const, query: 'gaming highlights' },
  { id: 'news', label: 'News', endpoint: 'search' as const, query: 'breaking news' },
  { id: 'sports', label: 'Sports', endpoint: 'search' as const, query: 'sports highlights' },
];

const YOUTUBE_BASE_URL = 'https://www.googleapis.com/youtube/v3';
const API_KEY = YOUTUBE_API_KEY;

const YouTubePicker: React.FC<YouTubePickerProps> = ({ onVideoSelect, onClose, isProcessing = false }) => {
  const { theme } = useTheme();
  const [selectedCategory, setSelectedCategory] = useState<string>('lgbt');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [videos, setVideos] = useState<YouTubeVideo[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const requestIdRef = useRef(0);
  const videoCache = useRef<Map<string, YouTubeVideo[]>>(new Map());

  const canFetch = useMemo(() => Boolean(API_KEY && API_KEY.trim().length > 0), []);

  const buildCacheKey = useCallback((endpoint: string, params: Record<string, string>) => {
    const sortedEntries = Object.entries(params).sort(([a], [b]) => a.localeCompare(b));
    return `${endpoint}:${JSON.stringify(sortedEntries)}`;
  }, []);

  const mapVideoResults = useCallback((items: YouTubeApiSearchResult[]): YouTubeVideo[] => {
    return items
      .map((item) => {
        const snippet = item.snippet;
        if (!snippet) return null;

        const rawId = typeof item.id === 'string' ? item.id : item.id?.videoId;
        if (!rawId) return null;

        return {
          id: rawId,
          title: snippet.title || 'Untitled video',
          description: snippet.description || '',
          channelTitle: snippet.channelTitle || 'Unknown channel',
          publishedAt: snippet.publishedAt || '',
          thumbnail:
            snippet.thumbnails?.high?.url ||
            snippet.thumbnails?.medium?.url ||
            `https://i.ytimg.com/vi/${rawId}/mqdefault.jpg`,
        };
      })
      .filter(Boolean) as YouTubeVideo[];
  }, []);

  const fetchVideos = useCallback(
    async (endpoint: 'videos' | 'search', params: Record<string, string> = {}) => {
      if (!canFetch) return;

      const cacheKey = buildCacheKey(endpoint, params);
      const cached = videoCache.current.get(cacheKey);
      if (cached) {
        setVideos(cached);
      }

      setIsLoading(true);
      setError(null);
      const fetchId = ++requestIdRef.current;

      const url = new URL(`${YOUTUBE_BASE_URL}/${endpoint}`);
      url.searchParams.set('key', API_KEY);
      url.searchParams.set('maxResults', '24');

      if (endpoint === 'videos') {
        url.searchParams.set('part', 'snippet,contentDetails,statistics');
        url.searchParams.set('regionCode', 'US');
      } else {
        url.searchParams.set('part', 'snippet');
        url.searchParams.set('type', 'video');
        url.searchParams.set('videoEmbeddable', 'true');
        url.searchParams.set('safeSearch', 'moderate');
      }

      Object.entries(params).forEach(([key, value]) => url.searchParams.set(key, value));

      try {
        const response = await fetch(url.toString());
        if (!response.ok) {
          throw new Error(`YouTube request failed: ${response.status}`);
        }
        const data = await response.json();
        const items: YouTubeApiSearchResult[] = Array.isArray(data.items) ? data.items : [];
        const mapped = mapVideoResults(items);
        videoCache.current.set(cacheKey, mapped);

        if (fetchId === requestIdRef.current) {
          setVideos(mapped);
        }
      } catch (err) {
        if (fetchId === requestIdRef.current) {
          setError(
            err instanceof Error
              ? err.message
              : 'Unable to load videos right now. Please try again shortly.',
          );
        }
      } finally {
        if (fetchId === requestIdRef.current) {
          setIsLoading(false);
        }
      }
    },
    [buildCacheKey, canFetch, mapVideoResults],
  );

  const handleCategoryChange = (categoryId: string) => {
    const category = YOUTUBE_CATEGORIES.find((cat) => cat.id === categoryId);
    if (!category) return;
    setSelectedCategory(category.id);

    if (category.endpoint === 'videos') {
      fetchVideos('videos', { chart: 'mostPopular' });
    } else if (category.endpoint === 'search') {
      fetchVideos('search', { q: category.query ?? 'youtube' });
    }
  };

  const handleSearch = async (query: string) => {
    if (!query.trim()) {
      handleCategoryChange('trending');
      return;
    }

    setSelectedCategory('');
    await fetchVideos('search', { q: query.trim() });
  };

  const handleVideoSelect = (video: YouTubeVideo) => {
    if (isProcessing) return;
    onVideoSelect(video);
  };

  useEffect(() => {
    if (canFetch) {
      handleCategoryChange('lgbt');
    }
  }, [canFetch]);

  const renderContent = () => {
    if (!canFetch) {
      return (
        <div
          className={`flex flex-col items-center justify-center w-full rounded-2xl border p-4 sm:p-6 text-center ${
            theme === 'dark'
              ? 'border-gray-900 bg-gray-900/30 text-gray-300'
              : 'border-gray-200 bg-gray-50 text-gray-700'
          }`}
        >
          <AlertCircle className="w-8 h-8 mb-3 text-orange-500" />
          <p className="text-sm font-semibold">YouTube API key missing</p>
          <p className="text-xs mt-1">
            Set <code className="px-1 py-0.5 rounded bg-black/10">VITE_YOUTUBE_API_KEY</code> to enable video search.
          </p>
        </div>
      );
    }

    if (error) {
      return (
        <div
          className={`flex flex-col items-center justify-center w-full rounded-2xl border p-4 sm:p-6 text-center ${
            theme === 'dark'
              ? 'border-gray-900 bg-gray-900/30 text-gray-300'
              : 'border-gray-200 bg-gray-50 text-gray-700'
          }`}
        >
          <AlertCircle className="w-8 h-8 mb-3 text-red-500" />
          <p className="text-sm font-semibold">Failed to load videos</p>
          <p className="text-xs mt-1">{error}</p>
          <button
            type="button"
            onClick={() => handleCategoryChange(selectedCategory || 'trending')}
            className={`mt-3 px-3 py-1.5 rounded-lg text-xs font-semibold ${
              theme === 'dark'
                ? 'bg-gray-900/60 text-white hover:bg-gray-900/80'
                : 'bg-gray-900 text-white hover:bg-black'
            }`}
          >
            Try Again
          </button>
        </div>
      );
    }

    if (isLoading && videos.length === 0) {
      return (
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 sm:gap-4">
          {Array.from({ length: 6 }).map((_, idx) => (
            <div
              key={idx}
              className={`rounded-2xl h-32 sm:h-36 animate-pulse ${
                theme === 'dark' ? 'bg-gray-900/40' : 'bg-gray-100'
              }`}
            />
          ))}
        </div>
      );
    }

    if (videos.length === 0) {
      return (
        <div
          className={`w-full rounded-2xl border p-5 text-center text-sm font-medium ${
            theme === 'dark'
              ? 'border-gray-900 bg-gray-900/30 text-gray-400'
              : 'border-gray-200 bg-gray-50 text-gray-500'
          }`}
        >
          No videos found for your search. Try a different query.
        </div>
      );
    }

    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4">
        {videos.map((video) => (
          <motion.button
            key={video.id}
            type="button"
            disabled={isProcessing}
            onClick={() => handleVideoSelect(video)}
            whileHover={!isProcessing ? { scale: 1.02 } : {}}
            whileTap={!isProcessing ? { scale: 0.97 } : {}}
            className={`rounded-2xl border overflow-hidden text-left transition-all duration-150 ${
              theme === 'dark'
                ? 'border-gray-900 bg-gray-900/40 hover:border-white/30'
                : 'border-gray-200 bg-white hover:border-gray-400'
            } ${isProcessing ? 'opacity-60 cursor-not-allowed' : 'cursor-pointer'}`}
          >
            <div className="relative aspect-video w-full bg-black/40">
              <img
                src={video.thumbnail}
                alt={video.title}
                className="w-full h-full object-cover"
                loading="lazy"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent" />
            </div>
            <div className="p-3 flex flex-col gap-1">
              <p className={`text-sm font-semibold line-clamp-2 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                {video.title}
              </p>
              <p className={`text-xs ${theme === 'dark' ? 'text-gray-400' : 'text-gray-600'}`}>
                {video.channelTitle}
              </p>
              {video.publishedAt && (
                <p className="text-[11px] text-gray-500">
                  {new Date(video.publishedAt).toLocaleDateString()}
                </p>
              )}
            </div>
          </motion.button>
        ))}
      </div>
    );
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 12 }}
      transition={{ duration: 0.25, ease: [0.4, 0, 0.2, 1] }}
      className={`py-4 border-t border-b ${
        theme === 'dark' ? 'bg-gray-950/90 border-gray-900' : 'bg-white/95 border-gray-200'
      }`}
    >
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3 min-w-0">
          <div
            className={`w-11 h-11 rounded-2xl flex items-center justify-center ${
