// helpers/safeUrl.ts
export function buildSafeURL(
    baseUrl: string,
    path: string | undefined | null,
    allowedHosts: string[] = []
  ): string | null {
    try {
      if (!path) return null;

      // Tam URL mi, yoksa relative mi kontrol et
      const url = path.startsWith("http") ? new URL(path) : new URL(path, baseUrl);

      // Protokol güvenli mi kontrol et
      if (url.protocol !== "https:" && url.protocol !== "http:") {
        console.warn("Blocked unsafe URL protocol:", url.protocol);
        return null;
      }

      // Eğer allowedHosts listesi varsa, hostu kontrol et
      if (allowedHosts.length > 0 && !allowedHosts.includes(url.hostname)) {
        console.warn("Blocked external host:", url.hostname);
        return null;
      }

      // URL başarılı şekilde doğrulandı
      return url.href;
    } catch (err) {
      console.warn("Invalid URL:", err);
      return null;
    }
  }


export function generatePlaceImage(seed : unknown) : string{
  const safeSeed = String(seed ?? 'guest');
  const randColor = pickSeededColorsString(safeSeed, 3);
  return `${PLACE_AVATAR_URL}${encodeURIComponent(safeSeed)}&backgroundColor=${randColor}&backgroundType=gradientLinear,solid`;
}


export function generateFallbackImage(seed : unknown) : string{
  const safeSeed = String(seed ?? 'guest');
  const randColor = pickSeededColorsString(safeSeed, 3);
  return `${DEFAULT_AVATAR_URL}${encodeURIComponent(safeSeed)}&backgroundColor=${randColor}&backgroundType=gradientLinear,solid`;
}

export function getSafeImageURL(
    attachment: unknown,
    variant: string = "small"
  ): string | null {
    const serviceURI = serviceURL[defaultServiceServerId]
    try {
      // Try multiple path structures:
      // 1. attachment.file.variants.image[variant].url (for nested file structure like avatar/cover)
      // 2. attachment.variants.image[variant].url (for direct file structure like media)
      // 3. attachment.file.variants.video[variant].url (for video files)
      // 4. attachment.variants.video[variant].url (for direct video structure)
      const path = attachment?.file?.variants?.image?.[variant]?.url || 
                 attachment?.variants?.image?.[variant]?.url ||
                 attachment?.file?.variants?.video?.[variant]?.url ||
                 attachment?.variants?.video?.[variant]?.url;

      if (!path) return null;

      // Eğer path mutlak değilse base URL ile birleştir
      const url = path.startsWith("http") ? new URL(path) : new URL(path, serviceURI);

      // Sadece http veya https izin ver
      if (!["https:", "http:"].includes(url.protocol)) {
        return null;
      }

      return url.href.toString();

    } catch (err) {

      return null;
    }

  }

export function getSafeImageURLEx(
    publicId : unknown,
    attachment: unknown,
    variant: string = "small"
  ): string | null {
    const serviceURI = serviceURL[defaultServiceServerId]
    try {
      // Try multiple path structures:
      // 1. attachment.file.variants.image[variant].url (for nested file structure like avatar/cover)
      // 2. attachment.variants.image[variant].url (for direct file structure like media)
      // 3. attachment.file.variants.video[variant].url (for video files)
      // 4. attachment.variants.video[variant].url (for direct video structure)
      const path = attachment?.file?.variants?.image?.[variant]?.url || 
                 attachment?.variants?.image?.[variant]?.url ||
                 attachment?.file?.variants?.video?.[variant]?.url ||
                 attachment?.variants?.video?.[variant]?.url;

      if (!path) {
        return generateFallbackImage(publicId)
      };

      // Eğer path mutlak değilse base URL ile birleştir
      const url = path.startsWith("http") ? new URL(path) : new URL(path, serviceURI);

      // Sadece http veya https izin ver
      if (!["https:", "http:"].includes(url.protocol)) {
           return generateFallbackImage(publicId)
      }

      return url.href.toString();

    } catch (err) {
         return generateFallbackImage(publicId)
    }

  }

  export function getImageURL(attachment: unknown, variant: string = "small"): string | null {
    return getSafeImageURL(attachment, variant);
  }


export function formatLastSeen(lastOnline: string): string {
  const now = new Date();
  const lastSeenDate = new Date(lastOnline);
  const diffInMinutes = Math.floor((now.getTime() - lastSeenDate.getTime()) / (1000 * 60));

  if (diffInMinutes < 1) return 'Just now';
  if (diffInMinutes < 60) return `${diffInMinutes}m ago`;

  const diffInHours = Math.floor(diffInMinutes / 60);
  if (diffInHours < 24) return `${diffInHours}h ago`;

  const diffInDays = Math.floor(diffInHours / 24);
  if (diffInDays < 7) return `${diffInDays}d ago`;

  return 'Recently active';
}

export function calculateAge(dateOfBirth: string): number | string {
  const birthDate = new Date(dateOfBirth);
  if (isNaN(birthDate.getTime())) {
    return '-';
  }

  const today = new Date();
  let age = today.getFullYear() - birthDate.getFullYear();
  const monthDiff = today.getMonth() - birthDate.getMonth();

  if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
    age--;
  }

  return age;
}


export function urlBase64ToUint8Array(base64String: string) {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/\-/g, '+').replace(/_/g, '/');

  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);

  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}

export const random = (min: number, max: number): number => Math.random() * (max - min) + min;

export const getLocalizedContent = (contentObj: Record<string, unknown> | undefined, languageCode: string): unknown => {
  if (!contentObj) return "";

  // Önce istenen dilde içerik var mı kontrol et
  if (contentObj[languageCode]) return contentObj[languageCode];

  // Yoksa ilk bulunan değeri döndür
  const values = Object.values(contentObj);
  if (values.length > 0) return values[0];

  return "";
}

import { useRef, useEffect, useCallback } from 'react';

interface UseInfiniteScrollOptions {
  loading: boolean;
  hasNextPage: boolean;
  onLoadMore: () => void;
  root?: Element | null;
  rootMargin?: string;
  threshold?: number;
}

const useInfiniteScroll = ({
  loading,
  hasNextPage,
  onLoadMore,
  root = null,
  rootMargin = '0px',
  threshold = 1.0,
}: UseInfiniteScrollOptions) => {
  const observer = useRef<IntersectionObserver | null>(null);

  const lastElementRef = useCallback(
    (node: Element | null) => {
      if (loading) return;
      if (observer.current) observer.current.disconnect();

      observer.current = new IntersectionObserver(
        (entries) => {
          if (entries[0].isIntersecting && hasNextPage && !loading) {
            onLoadMore();
          }
        },
        { root, rootMargin, threshold }
      );

      if (node) observer.current.observe(node);
    },
    [loading, hasNextPage, onLoadMore, root, rootMargin, threshold]
  );

  return lastElementRef;
};

export default useInfiniteScroll;

import { useEffect, useRef } from 'react';
import { createProgram, createShader } from '../helpers/webgl';
import type { Vibe } from '../types';

const VERTEX_SHADER_SOURCE = `
    attribute vec4 a_position;
    attribute vec2 a_texcoord;
    varying vec2 v_texcoord;
    void main() {
        gl_Position = a_position;
        v_texcoord = a_texcoord;
    }
`;

const FRAGMENT_SHADER_SOURCE = `
    precision highp float;
    varying vec2 v_texcoord;

    uniform sampler2D u_tex_from;
    uniform sampler2D u_tex_to;

    uniform vec2 u_resolution; // Canvas resolution for aspect ratio
    uniform vec2 u_res_from;   // 'From' media resolution
    uniform vec2 u_res_to;     // 'To' media resolution

    uniform float u_progress;   // 0.0 to 1.0 transition progress
    uniform float u_velocity;   // Scroll velocity for distortion intensity

    // Calculates UVs to make a texture cover a plane without distortion
    vec2 getCoverUv(vec2 uv, vec2 planeRes, vec2 mediaRes) {
        vec2 ratio = vec2(
            min((planeRes.x / planeRes.y) / (mediaRes.x / mediaRes.y), 1.0),
            min((planeRes.y / planeRes.x) / (mediaRes.y / mediaRes.x), 1.0)
        );
        return uv * ratio + (1.0 - ratio) * 0.5;
    }

    void main() {
        float distortion = clamp(abs(u_velocity) * 0.05, 0.0, 0.1);

        vec2 centeredUv = v_texcoord - 0.5;
        float radius = length(centeredUv);
        float distortionFactor = smoothstep(0.0, 0.5, radius);
        vec2 distortedUv = centeredUv + normalize(centeredUv) * distortion * distortionFactor * sin(radius * 10.0 - u_progress * 3.14159);
        distortedUv += 0.5;

        vec2 uv_from = distortedUv;
        uv_from.y -= u_progress;

        vec2 uv_to = distortedUv;
        uv_to.y += (1.0 - u_progress);

        vec2 cover_uv_from = getCoverUv(uv_from, u_resolution, u_res_from);
        vec2 cover_uv_to = getCoverUv(uv_to, u_resolution, u_res_to);

        // To prevent edge artifacts (thin lines) on some GPUs, especially mobile,
        // we inset the texture coordinates by half a pixel (texel).
        // This is more robust than a fixed epsilon value as it's resolution-independent.
        vec2 half_texel_from = 0.5 / u_res_from;
        vec2 half_texel_to   = 0.5 / u_res_to;

        vec2 clamped_uv_from = clamp(cover_uv_from, half_texel_from, 1.0 - half_texel_from);
        vec2 clamped_uv_to   = clamp(cover_uv_to, half_texel_to,   1.0 - half_texel_to);

        vec4 color_from = texture2D(u_tex_from, clamped_uv_from);
        vec4 color_to = texture2D(u_tex_to, clamped_uv_to);

        float fade_progress = smoothstep(0.0, 1.0, u_progress);

        gl_FragColor = mix(color_from, color_to, fade_progress);
    }
`;

interface WebGLReelsOptions {
    canvasRef: React.RefObject<HTMLCanvasElement>;
    vibes: Vibe[];
    onActiveIndexChange: (index: number) => void;
    isMuted: boolean;
    onActiveMediaLoadingChange?: (isLoading: boolean) => void;
}

