  }, [username, authUser, isAuthenticated, setUser, setError, setLoading]); // Removed api, added authUser and isAuthenticated

  // Fetch posts based on active tab
  useEffect(() => {
    const fetchUserPosts = async () => {
      // Don't fetch if on profile tab
      if (activeTab === 'profile') {
        return;
      }

      try {
        setPostsLoading(true);
        setError(null);

        let response;

        if (activeTab === 'posts') {
          // Fetch user posts
          response = await api.fetchUserPosts({
            user_id: user?.public_id,
            limit: 20,
            cursor: ""
          });
        } else if (activeTab === 'replies') {
          // Fetch user replies
          response = await api.fetchUserPostReplies({
            user_id: user?.public_id,
            limit: 20,
            cursor: ""
          });
        } else if (activeTab === 'likes') {
          // Fetch user liked posts
          response = await api.fetchUserPostLikes({
            user_id: user?.public_id,
            limit: 20,
            cursor: ""
          });
        }

        // Set posts from API response
        if (response && response.posts) {
          setPosts(response.posts);
        } else if (response && Array.isArray(response)) {
          setPosts(response);
        } else {
          setPosts([]);
        }
      } catch (err: unknown) {
        console.error('Error fetching posts:', err);
        setError((err as { response?: { data?: { message?: string } } }).response?.data?.message || 'Failed to load posts');
        setPosts([]);
